#!/usr/bin/env node
// Wraps the assembled Jotform IIFE in the GTM Custom HTML deploy shell:
// <script>, header, EC_FORM_CONFIG block. The IIFE is copied byte-for-byte.
'use strict';
const fs = require('fs');
const [IIFE, OUT] = process.argv.slice(2);
const iife = fs.readFileSync(IIFE, 'utf8');

const header = `<script>
/* UFT Jotform Standalone v3.3.0-jotform.1 | Author: Iyke Abel | MIT
 * Linkedin: https://www.linkedin.com/in/iykeabel/
 * Email: abeliyke05@gmail.com
 *
 * Generated by assemble-standalone.js from universal v3.3.0 + the Jotform
 * module (patch-universal-jotform.js). The shared core is byte-identical to
 * the universal v3.3.0; only other platforms were removed and the
 * namespacing below applied. Do not hand-edit: patch the module and re-run
 * the pipeline so the standalone and the universal candidate stay in step.
 *
 * Events: jotform_form_success | jotform_form_failed (source embeds only)
 *         ec_form_interaction, ec_tracker_initialized
 * GTM trigger: ^jotform_form_(success|failed)$   (regex matching ON)
 *
 * IFRAME / JS / LIGHTBOX EMBEDS (form fields are cross-origin: no PII)
 *   postmessage      Jotform Thank You screen posts submission-completed
 *   iframe_reload    frame navigated after the visitor focused into it
 *                    (inferred; dropped under strictSuccess)
 *   submit_referrer  redirect mode: next page load has referrer
 *                    submit.jotform.com, navigation type "navigate"
 *                    (verified live; fires on any URL, never on refresh)
 *   stored_recall    redirect mode with referrer stripped (inferred)
 * SOURCE-CODE EMBEDS (form.jotform-form in the page)
 *   full field capture, classifier keys (fullname, email, phone, street...),
 *   failure on li.form-line-error, success at pagehide after a clean
 *   submit (inferred) or on the destination page via submit_referrer
 *
 * Isolation (safe alongside other standalones; NOT alongside the universal):
 *   load guard    window._ec_jotform_tracker_loaded
 *   storage key   ec_jotform_form_data   marker ec_jotform_pending (no PII)
 *   queue key     ec_jotform_form_queue
 *   debug API     window._ecFormTrackers.jotform.status()
 *   SHARED on purpose: ec_form_dedupe, ec_attribution
 * Extra config (optional): jotformSubmitHosts: ['forms.example.com'] for
 *   Enterprise custom submit domains; jotformReloadGraceMs (default 1500)
 * Comments are stripped to keep GTM headroom; documented source:
 *   jotform-module.src.js + universal-form-tracking-v3.1.0.js
 */
window.EC_FORM_CONFIG = {
  debug: false,              // set true only while testing
  hashPii: false,            // emit normalized plaintext, let each platform tag hash
  rawFields: false,          // safest for GA4 - drops ec_raw_fields entirely
  defaultCountryCode: '1',   // fallback only; a country field on the form wins
  countryCodeField: '',      // optional: exact field name holding an ISO2 or dial code
  strictSuccess: false       // true = drop iframe_reload / pagehide / stored_recall guesses
};
`;
const out = header + iife + '</script>\n';
fs.writeFileSync(OUT, out);
console.log(OUT, out.length, 'chars (GTM limit 102,400; headroom', 102400 - out.length + ')');
